package com.domenota.medialoader.ui.screens.gallery

import android.graphics.BitmapFactory
import android.util.Base64
import androidx.compose.foundation.Image
import androidx.compose.runtime.Composable
import androidx.compose.runtime.remember
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.asImageBitmap
import androidx.compose.ui.layout.ContentScale

/** Approved v10 HTML reference: exact user-reviewed PNG icon pixels, not Material substitutes. */
private val galleryV10Png = mapOf(
    "album" to "",
    "wallpaper" to "",
    "info" to "",
    "extract" to "",
    "cutout" to "",
    "photoedit_menu" to "",
    "watermark" to "",
    "cast" to "",
    "lens" to "",
    "copy" to "",
    "loop" to "",
    "speed" to "",
    "live" to "",
    "share" to "",
    "photoedit" to "",
    "cut" to "",
    "heart" to "",
    "trash" to "",
    "more" to "",
    "music" to "",
    "open" to "",
    "lock" to "",
    "rotate" to "",
)

@Composable
internal fun GalleryV10Icon(icon: String, modifier: Modifier = Modifier) {
    val bitmap = remember(icon) { galleryV10Png[icon]?.let { value ->
        val bytes = Base64.decode(value, Base64.DEFAULT)
        BitmapFactory.decodeByteArray(bytes, 0, bytes.size)?.asImageBitmap()
    } }
    bitmap?.let { Image(bitmap = it, contentDescription = null, modifier = modifier, contentScale = ContentScale.Fit) }
}
